import{_ as n,c as i,o as t,a2 as r}from"./chunks/framework.CIiVzG-O.js";const f=JSON.parse('{"title":"Häufig gestellte Fragen","description":"Antworten zu Preis, Datenschutz, unterstützten Macs, Ordnern, Sprachen und zur Wiederherstellung eines Kaufs.","frontmatter":{"title":"Häufig gestellte Fragen","description":"Antworten zu Preis, Datenschutz, unterstützten Macs, Ordnern, Sprachen und zur Wiederherstellung eines Kaufs."},"headers":[],"relativePath":"de/guide/faq.md","filePath":"de/guide/faq.md","lastUpdated":1794296122000}'),a={name:"de/guide/faq.md"};function s(h,e,d,l,u,o){return t(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="haufig-gestellte-fragen" tabindex="-1">Häufig gestellte Fragen <a class="header-anchor" href="#haufig-gestellte-fragen" aria-label="Permalink to &quot;Häufig gestellte Fragen&quot;">​</a></h1><h3 id="ist-qdiff-kostenlos" tabindex="-1">Ist qDiff kostenlos? <a class="header-anchor" href="#ist-qdiff-kostenlos" aria-label="Permalink to &quot;Ist qDiff kostenlos?&quot;">​</a></h3><p>Ja. Jeder Vergleich, jede Ansicht und jeder Export funktioniert ohne Bezahlung. Die kostenlose Version zeigt lediglich einen kleinen „Nicht lizenziert“-Hinweis in der Tableiste. Ein einmaliger Kauf entfernt ihn und schließt künftige Premium-Extras ein. Es gibt kein Abo und keine Werbung.</p><h3 id="schaltet-der-kauf-weitere-funktionen-frei" tabindex="-1">Schaltet der Kauf weitere Funktionen frei? <a class="header-anchor" href="#schaltet-der-kauf-weitere-funktionen-frei" aria-label="Permalink to &quot;Schaltet der Kauf weitere Funktionen frei?&quot;">​</a></h3><p>Nein — alle Funktionen sind bereits verfügbar. Der Kauf entfernt den Hinweis. Falls wir später Premium-Extras ergänzen, gehören sie zum selben einmaligen Kauf und nicht zu einem neuen Produkt.</p><h3 id="wie-stelle-ich-meinen-kauf-wieder-her" tabindex="-1">Wie stelle ich meinen Kauf wieder her? <a class="header-anchor" href="#wie-stelle-ich-meinen-kauf-wieder-her" aria-label="Permalink to &quot;Wie stelle ich meinen Kauf wieder her?&quot;">​</a></h3><p>Öffnen Sie <strong>Einstellungen → Premium</strong> und wählen Sie <strong>Käufe wiederherstellen</strong>. Käufe sind an Ihre Apple ID gebunden und gelten daher auch auf Ihren anderen Macs.</p><h3 id="welche-macs-werden-unterstutzt" tabindex="-1">Welche Macs werden unterstützt? <a class="header-anchor" href="#welche-macs-werden-unterstutzt" aria-label="Permalink to &quot;Welche Macs werden unterstützt?&quot;">​</a></h3><p>macOS 12 oder neuer, auf Macs mit Apple-Chip und mit Intel-Prozessor. Siehe <a href="./download.html#system-requirements">Systemvoraussetzungen</a>.</p><h3 id="brauche-ich-ein-konto-oder-eine-internetverbindung" tabindex="-1">Brauche ich ein Konto oder eine Internetverbindung? <a class="header-anchor" href="#brauche-ich-ein-konto-oder-eine-internetverbindung" aria-label="Permalink to &quot;Brauche ich ein Konto oder eine Internetverbindung?&quot;">​</a></h3><p>Nein. qDiff arbeitet offline, benötigt keine Anmeldung und hat keinen Hintergrunddienst. Es öffnet nur die Dateien und Ordner, die Sie auswählen.</p><h3 id="kann-es-ganze-ordner-und-archive-vergleichen" tabindex="-1">Kann es ganze Ordner und Archive vergleichen? <a class="header-anchor" href="#kann-es-ganze-ordner-und-archive-vergleichen" aria-label="Permalink to &quot;Kann es ganze Ordner und Archive vergleichen?&quot;">​</a></h3><p>Ja. Ordner öffnen sich als Baum mit Statusfiltern sowie Kopier- und Synchronisierungsaktionen. Ein .zip- oder .tar-Archiv lässt sich ohne Entpacken wie ein Ordner vergleichen.</p><h3 id="was-ist-mit-bildern-und-nicht-text-dateien" tabindex="-1">Was ist mit Bildern und Nicht-Text-Dateien? <a class="header-anchor" href="#was-ist-mit-bildern-und-nicht-text-dateien" aria-label="Permalink to &quot;Was ist mit Bildern und Nicht-Text-Dateien?&quot;">​</a></h3><p>Bilder lassen sich nebeneinander oder als Überlagerung ansehen. Dateien, die kein reiner Text sind, können bis ins kleinste Detail verglichen werden. Siehe <a href="./more.html">weitere Vergleichsmöglichkeiten</a>.</p><h3 id="werden-meine-dateien-hochgeladen-oder-ausgewertet" tabindex="-1">Werden meine Dateien hochgeladen oder ausgewertet? <a class="header-anchor" href="#werden-meine-dateien-hochgeladen-oder-ausgewertet" aria-label="Permalink to &quot;Werden meine Dateien hochgeladen oder ausgewertet?&quot;">​</a></h3><p>Nein. Es wird nichts gesammelt, verfolgt oder synchronisiert. Die vollständige Erklärung finden Sie in der <a href="./../privacy/">Datenschutzerklärung</a>.</p><h3 id="gibt-es-die-oberflache-auch-auf-deutsch-und-in-anderen-sprachen" tabindex="-1">Gibt es die Oberfläche auch auf Deutsch und in anderen Sprachen? <a class="header-anchor" href="#gibt-es-die-oberflache-auch-auf-deutsch-und-in-anderen-sprachen" aria-label="Permalink to &quot;Gibt es die Oberfläche auch auf Deutsch und in anderen Sprachen?&quot;">​</a></h3><p>Ja — Englisch, vereinfachtes Chinesisch, traditionelles Chinesisch, Japanisch, Deutsch, Spanisch und Französisch, jeweils in heller und dunkler Darstellung.</p><h3 id="etwas-funktioniert-nicht-was-soll-ich-tun" tabindex="-1">Etwas funktioniert nicht. Was soll ich tun? <a class="header-anchor" href="#etwas-funktioniert-nicht-was-soll-ich-tun" aria-label="Permalink to &quot;Etwas funktioniert nicht. Was soll ich tun?&quot;">​</a></h3><p><a href="./support.html">Kontaktieren Sie uns</a> mit Ihrer macOS-Version und einer kurzen Beschreibung dessen, was passiert ist. Ein Screenshot hilft sehr.</p>',21)])])}const g=n(a,[["render",s]]);export{f as __pageData,g as default};
